insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e37e687b-c171-4e4a-b17d-9ae50f0a2b9f', 'ja', 'うまくいかなかった場面で自信が傷つく、本当の原因は何ですか？', '["その場面そのものではなく、繰り返し再生している物語", "起きたことを、周りがどう受け止め、どう反応したか", "その出来事の、実際の深刻さと気まずさ"]'::jsonb, '問題はその場面ではなく、再生し続けている記憶のほうです。')
