insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8219bd4-82ca-488f-a68f-22ee4942c702', 'ja', '自信が育っている証拠になるのは、どれですか？', '["ためらいがあっても、口を開くこと", "心地よいと感じるより、1秒長く目を合わせること", "準備ができたと感じるまで待つこと", "やめたほうが楽なときに、最後までやり通すこと"]'::jsonb, '証拠は、居心地の悪さがあっても行動することから生まれます。')
