insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('784400be-2ea4-4606-85a5-fb25457e3b9c', 'ja', '話す前に、プレッシャーが高まり、頭の中が駆けめぐります。何が助けになりますか？', '["頭の中で言葉をリハーサルする", "落ち着くまで、その場を避ける", "落ち着いて一度吸い、コントロールしながら一度吐く"]'::jsonb, '呼吸に意識を向けることで、主導権が自分にあることを体に思い出させます。')
