insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6cd4ab05-6a0e-4e05-9ef2-09775c5c9496', 'ja', '低いエネルギーは、なぜ人を遠ざけることがあるのですか？', '["映し取るのが、心地よくないから", "傲慢さを伝えるから", "関心がないように見えるから"]'::jsonb, '人は、重く感じる状態を本能的に避けます。エネルギーは、前向きに保ちましょう。')
