insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e40cadb9-6906-42bf-b334-b269e634ab6e', 'ja', '声をかける前に、どうすればエネルギーを高められますか？', '["少し体を動かし、ほほえみ、前向きな言葉を自分にかける", "状況を、もっと長く分析する", "自信が湧いてくるまで待つ", "緊張を避けるために、その場から引く"]'::jsonb, '体を動かすと、すぐに状態が切り替わり、エネルギーが高まります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d028ed4f-fd88-4a7c-8aab-17f7a78c6a9a', 'ja', 'ポジティブなエネルギーは、声をかけるときにどう影響しますか？', '["無意識のレベルで、人を引き寄せる", "やり取りを、自然に招き入れる", "完璧な見た目が必要になる"]'::jsonb, '良いエネルギーがあると、人は身を乗り出し、そばにいて気分が良くなります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('55639c7a-b396-4a1c-ae26-431442cfe270', 'ja', '本物の笑顔は、まず何を伝えますか？', '["惹かれている気持ち", "自信", "安全と温かさ", "遊び心"]'::jsonb, '笑顔は、一瞬で「安全だ」と読み取られます。言葉を交わす前から、助けになります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cfa95ebd-1b35-41c8-8a50-fbcb06fee6aa', 'ja', 'ほほえむと、なぜ人とのあいだの緊張が下がるのですか？', '["注意をそらすから", "前向きな感情の反応を引き起こすから", "緊張を隠すから"]'::jsonb, 'ほほえむと、言葉を交わす前に、二人の脳がどちらも前向きさを感じ取ります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2886592f-4bba-4b7d-bcfc-6547f1eb778e', 'ja', '本物の笑顔は、どうやって二人ともに前向きな反応を生むのですか？', '["神経系に、脅威を伝える", "神経の働きとして、気分を良くし、ストレスを減らす", "脳が、無意識のうちに前向きな感情を映し取る"]'::jsonb, '笑顔は、会話が始まる前に、お互いの前向きな気持ちを引き出します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2c9f06f7-4cf4-45f9-80cd-7c8fcac8c28c', 'ja', '承認に頼ることは、なぜ自信を損なうのですか？', '["プレッシャーを生むから", "表現を制限するから", "自己不信を伝えるから", "境界線を弱めるから"]'::jsonb, '承認を必要とすることは、自分で自分を認められていないことを伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7bd56cd8-1f4f-4678-8dce-d3e92a3e8932', 'ja', '彼女が、自分とは違う意見を話します。彼女の承認を求めずにいられるのは、どれですか？', '["和を保つために、すぐに同意する", "申し訳なさそうにせず、違う見方を丁寧に伝える", "彼女に合わせて、自分の意見を変える", "衝突を避けるために、黙っている"]'::jsonb, '自分の軸を落ち着いて保つことは、必死さを見せずに、自分で自分を認めていることを伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3fe6a5a2-4f72-4f9a-9d46-3a48ef587e96', 'ja', '承認を求めることは、なぜ惹かれる気持ちを遠ざけるのですか？', '["認められたいという必死さを伝えるから", "自分の価値を、彼女に受け入れられるかどうかに結びつけるから", "本心ではない振る舞いを生むから", "いつでも、より深いつながりを保証するから"]'::jsonb, '承認を求めることは、自己不信を伝えます。自分を受け入れていることは、強さを伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e562de05-8b81-429d-b188-fbe14cf83db2', 'ja', 'ある男性が、何か月も練習したあとも、まだ緊張します。何を物差しにするべきですか？', '["同じくらいの練習時間で、ほかの人のほうが速く上達しているかどうか", "以前はできなかったことが、今はできるかどうか", "今の自分のスキルが、もともと自信のある男性と比べてどうか"]'::jsonb, '意味のある物差しは、以前の自分より良くなっているかどうか、だけです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('586652d7-39f3-41aa-9a2f-cb693ae30050', 'ja', '他人と比べることは、なぜスキルを伸ばすうえで害になるのですか？', '["相手の出発点も、場数も、事情のすべても知らないから", "確実に失敗する、非現実的な期待を生むから", "内側の体験を外から見える結果と比べることになり、公平ではないから"]'::jsonb, '見えているのは相手の結果だけで、その出発点や事情は知りません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9250aace-fa4f-4d66-95e4-793349439200', 'ja', '声をかけることを軽く感じさせてくれるものは、何ですか？', '["結果に、自分が何者かを決めさせないこと", "断られることを、プロセスのふつうの一部として受け入れること", "上の両方"]'::jsonb, '結果が自分の価値を決めなければ、声をかけることは、それほど怖くなくなります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('53bacb30-3d41-4c17-a18d-8c00b9bc1398', 'ja', '人とのやり取りにおける「結果に左右されない」とは、どういうことですか？', '["相手の反応に関係なく、気持ちの安定を保つこと", "結果をまったく気にしないこと", "毎回、良い結果を無理やり引き出すこと", "安全でいるために、やり取りを避けること"]'::jsonb, '相手の反応に関係なく気分が安定していれば、主導権は自分に戻ってきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('83794883-664e-42e0-89fa-abc8d0f95334', 'ja', '「結果に左右されない」とは、実際にはどういう意味ですか？', '["やり取りの結果や成功を、まったく気にしないこと", "やり取りがどうなっても、気持ちの安定を保つこと", "自分の価値や気分が、特定の結果に結びついていないこと"]'::jsonb, '結果は今でも気になります。でも、それがどう感じ、どう行動するかを決めることは、もうありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39d1a173-8185-476b-ba48-a86f79e52a48', 'ja', '好意的な反応をうまく受け止める鍵は、何ですか？', '["彼女の注意を引きつけておこうと、もっとがんばること", "プレッシャーを避けるために、エネルギーを下げること", "失わないように、その場をコントロールすること", "その関心を生んだ、同じ自分のままでいること"]'::jsonb, '惹かれる気持ちを生んだその自分で、もう十分です。上乗せしたり、演じたりしてはいけません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b61bcf4-54dc-4de9-8ba8-813071e2e979', 'ja', '雰囲気は最高で、彼女が身を寄せてきます。頭が「次はどうする」と管理し始めます。どうするべきですか？', '["コントロールしようとせず、今この瞬間にいることへ戻る", "計画を立てるために、思考に任せる", "この機を逃すまいと、すぐに距離を縮める", "良い雰囲気から、身を引く"]'::jsonb, '物事がうまくいっているとき、するべきことは、リズムを保つことです。結果を管理することではありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0b5dc6ef-1cda-498e-932d-4939839666ad', 'ja', '好意的な反応は、なぜ人を不安定にすることがあるのですか？', '["欠乏の思考から、承認を求める行動を引き起こすから", "良い気分を失う恐れを呼び起こすから", "行動を何も調整しなくてよくなるから", "機を逃すまい、コントロールしようというプレッシャーを生むことがあるから"]'::jsonb, '好意的なサインは、「失うもの」を生みます。結果を守ろうとする状態に、切り替わらないようにしましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5956bc0c-e67e-486c-9121-0d4f3f555035', 'ja', '体を鍛えることは、周りが体の変化に気づく前に、まず何を変えますか？', '["トレーニングの知識と、自分を律する力", "自分自身の見え方と、内側の自信", "注目を集める力", "会話のスキルと愛嬌"]'::jsonb, '自信は、まず自分に対する内側の見方が良くなったときに育ちます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9ec8b2af-94c5-4b1c-a704-f2bd3e950b20', 'ja', '体を鍛えることは、どうやって自信を高めるのに役立ちますか？', '["自分を大切に扱っていることの、身体的な証拠になる", "女性から見て、目に見えて魅力的になる", "恋愛にも活かせる、自分を律する力が身につく", "人の集まる場での立ち位置が上がる"]'::jsonb, '体を鍛えると、まず自分自身の見え方が変わり、それが声をかける可能性を高めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d0c9fead-d08c-463e-82b3-6acbc68aa42b', 'ja', '体が鍛えられていることから来る自信の変化は、何によって生まれますか？', '["自分の体は、前より動けると信じること", "鏡の中に、自分で敬意を持てる体を見ること", "人のいる場面での自己監視が減ること", "周りから褒められること"]'::jsonb, '自分への敬意は、外からの承認が関わるずっと前に、行動を形づくります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('941578b4-3efd-48fd-bb43-567d6cc34570', 'ja', '身だしなみが整っていないと、第一印象にどう影響しますか？', '["女性は、より多くの努力を期待するようになる", "立ち位置の低さを伝える", "惹かれる気持ちが生まれる前に、最初のためらいを生む"]'::jsonb, '最初に目に入る手がかりが、会話が始まる前に、安心感と関心を左右します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('320c1b55-513d-40ef-8b8a-5575836c5e6c', 'ja', '身だしなみを整え続けることの、内面への主な効果は何ですか？', '["褒められることで、外から認められること", "意志の力で、無理に自信をつくり出すこと", "顔や体つきが、劇的に変わること", "がんばらなくても、冴えていて整っていると感じられること"]'::jsonb, '身だしなみは自分自身の見え方を変え、それが声をかける可能性を高めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c8f3b672-a516-497b-889c-0bb6535c7859', 'ja', '身だしなみを整えることの利点には、どんなものがありますか？', '["第一印象が良くなる", "内面の壁が減り、自然に振る舞える", "相手に、自分を大切にしていることが伝わる", "身だしなみに気を使わない男性より、有利になる"]'::jsonb, 'より整った第一印象、より自由な振る舞い、そして目に見える自分への敬意です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e694c46-0fd5-4820-84c0-2432a8fd7227', 'ja', '清潔にする習慣は、声をかけるときにどう役立ちますか？', '["惹かれる気持ちを妨げる小さな壁を、取り払ってくれる", "周りの人を気づかっていることが伝わる", "ほかの男性より、確実にいい香りがするようになる", "毎回、洗練された第一印象をつくれる"]'::jsonb, '清潔さは、距離を生む目に見えない引っかかりを取り除きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d0aa5e3a-b58e-4eea-8381-e21cbca6f874', 'ja', '清潔さを保つことは、実際には何をもたらしますか？', '["惹かれる気持ちが生まれるのを妨げる壁を、取り除く", "近い距離でやり取りするための、内面の確かさを生む", "より愛嬌があり、人付き合いの上手な人にしてくれる"]'::jsonb, '清潔だという安心感は、自己監視と、引っかかりを生む目に見えない壁をなくします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9b201136-be01-4de3-b7a9-41ab4fa02a38', 'ja', '良くないスタイルは、なぜ目に見えない引っかかりを生むのですか？', '["会話の流れを断ち切るから", "声の自信を下げるから", "最初の判断を、悪い方向に左右するから", "内向的だと伝えるから"]'::jsonb, '最初の判断は、やり取りが本格的に始まる前に、相手の心の開き方を左右します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c3ef8c23-3bd4-42a1-ba4a-0cc007c4f952', 'ja', '良いスタイルは、内面の自信にどう影響しますか？', '["ユーモアを良くする", "支配力を高める", "自分に気を取られることを減らす", "自己監視を減らす"]'::jsonb, '体に合った着心地のいい服は、注意を内側ではなく、外側に向けたままにしてくれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('02e91b80-7376-4e58-a593-604cc6b23a79', 'ja', '笑い声が無理をしているように感じられ、声も高くなっています。どんな練習が役立ちますか？', '["息を吸いながら、もっと大きな声で話す", "惹きつけるために、声を高くする", "考えを口にする前にひと呼吸置き、吐く息に乗せて話す", "緊張に合わせて、話すスピードを上げる"]'::jsonb, '吐く息に乗せてペースをコントロールすると、トーンと存在感が安定します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('03af7107-7650-4d54-b1a7-e9dee067e1b1', 'ja', '人が自分を監視し始めると、やり取りの中で何が変わりますか？', '["つながりが、演技に置き換わる", "表現が減る", "不安が消える"]'::jsonb, '自己監視は、本物のやり取りから意識をそらしてしまいます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0cfb0ca8-28d9-426f-80c4-d26b972acc51', 'ja', 'ある男性が、会話を頭の中で再生して、自分はぎこちなかったと結論づけます。何が起きていますか？', '["次に良くするために、失敗から学んでいる", "自分の振る舞いについて、現実的に見ている", "心が、事実ではなく恐れで空白を埋めている", "自己認識が、弱点を見つける助けになっている"]'::jsonb, 'あとから心が語る物語は、実際に起きたことの信頼できる記録ではありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1050b192-a012-4512-86fb-9ceb4d8087e7', 'ja', '本物の笑顔が生むことのある効果は、どれですか？', '["ストレスが減る", "話しかけやすい印象が増す", "警戒が下がる", "すぐに惹かれる気持ちが生まれる"]'::jsonb, '本物の笑顔は、会話が始まる前に温かさを伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1078c50b-deac-4399-9cc9-3872de90104c', 'ja', '自信の根底にある、中心的な変化は何ですか？', '["称賛されること", "すごいと思われること", "受け入れられること", "証明を必要としなくなること"]'::jsonb, '自分の価値が他人に左右されなくなったとき、自信は安定します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1d689f0a-9831-4f51-86c0-26f91d7c3192', 'ja', 'グラウンディングは、なぜ声をかける前の不安を和らげるのに役立つのですか？', '["不安な考えから、一時的に気をそらしてくれるから", "体の感覚が安全を伝え、脅威への反応を解除するから", "体に意識を向けることで、気づきを通じて自信が育つから"]'::jsonb, 'グラウンディングは、注意を頭の中から体の感覚へと移すことで働きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('219e0cdc-a9ad-455f-86bd-5424943faf26', 'ja', 'ある男性が、好意的な反応をもらった瞬間に「これを台無しにするな」と考えます。何が起こりますか？', '["そのプレッシャーが、ミスを避ける助けになる", "プレッシャーを生み、それが自分のエネルギーを変えてしまう", "その考えが、会話に乗り続ける意欲になる"]'::jsonb, '「失敗しないように」と管理することが、リラックスした関わり方に取って代わり、打ち解けた空気を損ないます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('259c1e7d-ff03-4cbb-8e6f-491608175612', 'ja', 'ポジティブなエネルギーは、実際には何をしますか？', '["そばにいると気分が良くなるので、人を引き寄せる", "立ち位置の高さを示すサインを通じて、すぐに惹かれる気持ちを生む", "言葉の説得力を高める", "やり取りを招き入れやすくする"]'::jsonb, 'ポジティブなエネルギーは人の気分を良くし、それが自然と人を引き寄せます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2aba3577-76b4-423a-898b-cb6e1f03d88d', 'ja', 'ある男性が、声をかけている最中に、高めの声で早口で話しています。何が起きていますか？', '["わくわくした気持ちが、落ち着きのなさとして伝わっている", "トーンが緊張を伝え、彼女は言葉を聞く前にそれを感じ取っている", "無意識のうちに、沈黙を埋めて流れを保とうとしている"]'::jsonb, 'トーンが急いでいたり、張りつめていたりすると、人は緊張を感じ取ります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('35e59aa9-31b1-4b02-af42-50fe8b4a375c', 'ja', 'ある男性は、言葉はぎこちないものの、エネルギーはすばらしいです。何が起こりますか？', '["それでも、やり取りは心地よく感じられる", "会話は失敗する", "関心がすぐに下がる", "周りは、彼の失敗に注目する"]'::jsonb, 'エネルギーが前向きに感じられると、人はそばにいることを楽しみます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('40266254-315c-41fe-9eba-7ad6413d86a3', 'ja', '最初の段階では、なぜ言葉よりも笑顔のほうがうまくいくのですか？', '["言葉は、リスクがあるように感じられるから", "顔のほうが、速く処理されるから", "笑顔は、意図をはっきり示すから", "沈黙は、自信があるように感じられるから"]'::jsonb, '脳は、言葉より先に顔を読みます。まずほほえんで、笑顔に助けてもらいましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43d2d9f6-2ffb-4330-8584-9a58b70d6399', 'ja', '体を鍛えることは、なぜ見た目以上に自信を築くのですか？', '["周りからの見られ方を、すぐに変えるから", "自分自身の見え方と、自分の体への敬意を高めるから", "内側の自己監視と迷いを減らすから"]'::jsonb, '体を鍛えることは、内面の確信を形づくり、雑音を減らして、自然な自信を高めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('46eb84b4-53da-484e-8846-fdb26ae3c785', 'ja', '長い目で見て、自信を強くするものは何ですか？', '["穏やかな感情", "はっきりした計画", "居心地の悪さを避けること", "恐れがあっても行動すること"]'::jsonb, '自信は、その場に立つ前ではなく、立ったあとに形づくられます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4ac6998e-65dd-431c-99de-be7a3f97072e', 'ja', '声をかけている最中に、肩がこわばり、目が泳ぎます。何を優先するべきですか？', '["姿勢と呼吸をゆるめて、緊張のサインを取り除く", "緊張を打ち消すために、もっと速く話す", "無理にでも、もっと強く目を合わせる", "自信があるように見せるために、身ぶりを大きくする"]'::jsonb, '体は、言葉が届くよりも先に、安全か緊張かを伝えています。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51ceb33f-6d3d-4110-8369-52ab53cc3b2c', 'ja', '彼女が強い関心を示していて、「これを台無しにしたくない」という衝動を感じます。どんな考え方が役立ちますか？', '["このめったにないチャンスは、必ず確保しなければならない", "安全策を取って、身を引く", "この瞬間にふさわしくなるために、勢いを上げる", "彼女の関心はうれしい。彼女を惹きつけた自分のままでいる"]'::jsonb, '関心を認めながら、それに執着したり、さらに追いかけたりしないことです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5423b03c-3be1-4925-81c1-77d8776ea860', 'ja', '目が合ったあと、彼女のほうへ歩いています。どんな表情が一番役立ちますか？', '["感情を出さない、まじめな顔", "無理につくった満面の笑み", "温かく、本物の笑顔を保つ", "クールでいるために、無表情"]'::jsonb, '本物の笑顔は、言葉を交わす前に、安全だと伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59af149f-a4e1-4e59-9e5c-79c015952617', 'ja', 'やり取りがうまくいきません。どう考えるべきですか？', '["「今のはうまくいかなかった。次は何を変えられるだろう」", "「自分は、根本的にこういうのが下手だ」", "「もともと得意な人もいる。自分は違う」", "「もう挑戦するのはやめよう」"]'::jsonb, '成長マインドセットは、断られたことを、上達のためのデータとして捉え直します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6050d9fa-5758-4a66-9d2a-4484751813c5', 'ja', 'ある男性が、注目されているときに、自分がどう見えるかをコントロールしようとします。その代償は何ですか？', '["自信がなく、周りの目を気にしているように見える", "周りがその演技に気づいて、否定的に反応する", "見え方を管理することで、自分らしさが減り、演技が増える"]'::jsonb, 'どう見えるかを管理しようとすればするほど、自分らしさは失われます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('695eb047-3678-474b-a13a-26682bf11d5f', 'ja', '腕を組み、エネルギーの低いまま、店に入ります。このあと何が起こりますか？', '["周りの人が、進んで話しかけてくる", "時間がたつにつれて、リラックスしてくる", "周りの人が、無意識のうちに避ける", "自分の言葉に、より重みが出る"]'::jsonb, '閉じたボディランゲージは、たとえつながりを求めていても、「引いている」と伝えてしまいます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6e9907b3-8130-4125-a5aa-e6b1a0898b60', 'ja', '人付き合いのスキルが長い目で見て上達するかどうかを決めるものは、何ですか？', '["最初から持っている、生まれつきの才能", "能力は練習で伸ばせるという信念", "つまずいても、努力を続けること", "自信を守るために、挑戦を避けること"]'::jsonb, 'スキルが伸びるのは、やめずに続けたときだけです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7ea9a0ee-49fd-4682-8888-bb7fba4dfa72', 'ja', '会話の途中で、腕は組んだままで、姿勢が崩れています。これは何を伝えていますか？', '["言葉とは裏腹に、居心地の悪さが自分を内側へ引き込んでいること", "力強く、自信のある存在感", "リラックスした、気楽なエネルギー", "意図した、ミステリアスな雰囲気"]'::jsonb, '緊張した体は、言葉の上での余裕を打ち消し、ずれを生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7f2e5b24-f05e-439d-9f03-8ea8d846f05a', 'ja', '店に入る前に、エネルギーが低いと感じます。何をすれば切り替えられますか？', '["良くなるまで、隅にいる", "無理に、もっと大きな声で会話する", "体を動かし、意識してほほえむ", "自然にそうなるまで、やり取りを避ける"]'::jsonb, '小さな行動が、エネルギーを前向きで、人を招き入れるものに切り替えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('80156644-8f30-46b7-9f70-3e7b0fbd786f', 'ja', '話そうとすると、胸が締めつけられ、頭の中が駆けめぐります。どんなグラウンディングの技法が役立ちますか？', '["良い結果を、繰り返し思い浮かべる", "無理に、もっと深い話題にする", "落ち着くまで、その場を避ける", "地面についた足を感じ、呼吸をゆっくりにする"]'::jsonb, 'グラウンディングが効くのは、注意を未来についての思考から、今の感覚へと移すからです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('82bb1ff8-f12d-487b-9b54-090588f0d69d', 'ja', '好意的な反応は、なぜ断られることよりもアドレナリンを急上昇させることがあるのですか？', '["成功は、もともと失敗より感情を強く揺さぶるから", "神経系は、脅威より報酬に強く反応するから", "「チャンスを失う恐れ」という、新しい恐れを生むから"]'::jsonb, '好意的なサインは、「失うもの」を生みます。結果を守ろうとする状態に、切り替わらないようにしましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8a5e8c45-7476-413e-8358-7c92cdbab538', 'ja', '時間とともに恐れを弱めるものは、何ですか？', '["プレッシャーの高い場面の前に、前向きな言葉を自分にかけること", "恐れのサインがあっても行動し、神経系を更新すること", "予測した痛みが起きなかった、一回一回のアプローチ", "考えることや心の準備ではなく、動くこと"]'::jsonb, '行動が予測を覆したとき、恐れはやわらぎます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8dc6c797-1c0b-443d-ab04-062afc92c412', 'ja', '承認を必要としなくなると、何が起こりますか？', '["自信がより安定する", "注目が減る", "やり取りが短くなる", "コントロールを失う"]'::jsonb, '自分の価値は、外からの承認に左右されません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8f1849bb-0b9f-4680-afff-7f0d273e5810', 'ja', '第一印象に影響する身体的な手がかりは、どれですか？', '["目の動き", "頭の中の考え", "姿勢"]'::jsonb, '目に見える手がかりは、一瞬で印象を形づくります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94983000-db09-40ee-ac8e-75de9d87d3f6', 'ja', '恐れがあっても行動すると、何が起こりますか？', '["行動しないことで、疑いが大きくなる", "「恐れがすべてを決めるわけではない」と脳が学ぶ", "経験を重ねることで、自分を信じる気持ちが強まる", "それでもやることから、自信が形づくられる"]'::jsonb, '何度も乗り越えることで、心は信頼できる証拠によって更新されます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9c28c269-1ab6-4f2a-9043-22fadc730b6b', 'ja', '声をかけるのをためらいますが、それでも声をかけ、悪いことは何も起こりません。これは何をもたらしますか？', '["脳が、この先の自分への信頼のために蓄える、小さな証拠", "すぐに手に入る、完璧な自信", "一時的な安心だけ"]'::jsonb, 'それでも行動するたびに、頼りにできる記録が積み上がっていきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a0b5f46b-7b16-4682-b089-7e8d882d5dea', 'ja', 'ほほえむことは、ほほえむ本人にどう役立ちますか？', '["姿勢を良くする", "気持ちを落ち着かせる物質を放出する", "支配力を高める"]'::jsonb, 'ほほえむと、神経化学物質が放出され、内面の状態が切り替わります。もっとほほえみましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a7253e20-5530-468a-a086-0f0e27b02b4b', 'ja', '避けることは、なぜ時間とともに恐れを大きくするのですか？', '["体に「避けるほうが安全だ」と教えるから", "向き合わないことで、恐れの反応を強めるから", "自信を少しずつ築くから"]'::jsonb, '身を引くことは、回避のループと恐れのサインを強めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b400f47c-56f1-455f-8258-5bf582c021f8', 'ja', '緊張を感じていますが、リラックスして見せたいと思っています。体を意図に合わせるのは、どれですか？', '["背筋を伸ばし、深く呼吸し、自分の言葉を自分でさえぎらない", "身を守るために、腕を組む", "プレッシャーを減らすために、目を合わせない", "エネルギーを発散するために、そわそわ動く"]'::jsonb, '開いた、安定した体は、演じなくても落ち着きを映し出します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b505f110-e322-4bf1-9300-fb0cc533a552', 'ja', '「彼女には好かれない」という疑いが浮かびます。どうするべきですか？', '["ノイズだと気づき、信じ込まずに流す", "間違いだと証明するために、その疑いと闘う", "現実的でいるために、それを信じる", "深く分析するために、繰り返し再生する"]'::jsonb, 'どんな考えが浮かぶかはコントロールできません。でも、それを信じるかどうかはコントロールできます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8441682-aa6b-4a9b-b7ac-97e0f2c1573d', 'ja', 'ポジティブなエネルギーは、なぜやり取りを引き寄せるのですか？', '["そばにいると、人は気分が良くなるから", "支配力を伝えるから", "注目を要求するから"]'::jsonb, '心地よい状態は、自然と人を引き寄せます。エネルギーは、前向きに保ちましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8999272-dae6-4926-b567-a975478a321d', 'ja', '会話が始まる前から、つながりを壊してしまうものは何ですか？', '["迷いを伝える、泳ぐ目と閉じた姿勢", "言葉は落ち着いて聞こえるのに、居心地の悪さを発しているこわばった体", "最初のひと言を間違えたり、テクニックがまずかったりすること"]'::jsonb, '居心地の悪さを示す体のサインは、言葉に関係なく、つながりを壊します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c5d60b8c-c34d-4089-81c4-a5f56034f361', 'ja', '人の多い部屋に入り、すべての視線が自分に向いているように感じます。何を自分に言い聞かせるべきですか？', '["みんなが、こちらを厳しく評価している", "なじむためには、完璧に振る舞わなければならない", "ほとんどの人は、こちらのことではなく、自分自身のことで頭がいっぱいだ", "その感覚が過ぎるまで、隠れている"]'::jsonb, '心は、自分に向けられた注目を大げさに見積もります。現実には、周りはそれほど見ていません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c8828ffa-d37b-4033-9da0-bd56a61641e5', 'ja', '会話は申し分なく流れ、彼女ははっきりと関心を示しています。避けるべきことは何ですか？', '["その場の流れのまま、自然に続けること", "彼女の好意的なサインに応えること", "リズムに余白を持たせること", "もっと承認を得ようと、さらにがんばること"]'::jsonb, '承認を求めるプレッシャーは、自然な流れを乱します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c918a4eb-10ec-4f35-a8de-8627f329a218', 'ja', '会話の途中で、胸が締めつけられ、呼吸が浅くなっているのを感じます。何に意識を向けるべきですか？', '["無理に、声を落ち着いて聞こえるようにする", "安定した、コントロールされた呼吸に戻る", "立て直すために、やり取りを終わらせる", "早く終わらせるために、話すスピードを上げる"]'::jsonb, '呼吸を整えると、言葉を落ち着かせようとする前に、声が安定します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc39682a-160f-459c-a7c6-83758e6a8ad3', 'ja', '体を鍛え続けることの、主な利点は何ですか？', '["外から認められるための、完璧な見た目", "自分自身の見え方と、内側の自信が良くなること", "見た目が、すぐに劇的に変わること", "意志の力で、無理に自信をつくり出すこと"]'::jsonb, '自分で敬意を持てる体は、がんばらなくても湧いてくる、内側からの確信を生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e0b7ae70-05c8-4c9c-8a5b-c48a3e0f6743', 'ja', '誰かに声をかける前に、体がこわばります。これは何を示していますか？', '["体の自然な反応であり、成長のチャンス", "弱さであり、やめる理由", "悪い結果が確実だということ", "この先もずっと、準備ができないということ"]'::jsonb, '恐れは、ふつうの生理的な反応であって、止まれという合図ではありません。動くことで、それが間違いだと証明されます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e172e286-a34d-4fba-a51e-7a29d03e5107', 'ja', '彼女はよく笑い、身を寄せ、腕に触れてきます。次にどうするべきですか？', '["エネルギーを上げて、彼女を感心させようともっとがんばる", "完璧なままにするために、何を言うかを考え始める", "リラックスしたまま、それまでと同じように続ける", "この機を逃すまいと、すぐに距離を縮める"]'::jsonb, '好意的な関心は、もっとがんばる合図ではありません。そのままでいる合図です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e56ee826-cd5b-4fb6-8005-84e669a0b1d7', 'ja', '声をかける前に恐れが湧いたとき、呼吸はなぜ助けになるのですか？', '["恐れから気をそらしてくれるから", "その瞬間をゆっくりにするから", "すぐに自信を高めるから", "神経系に、安全だと伝えるから"]'::jsonb, 'ゆっくりした呼吸は、体に安全だと伝え、行動する前の状態を落ち着かせます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e750c943-9bb0-4a66-892d-3442f22cd528', 'ja', '体がこわばっていると、なぜ愛嬌が通じないことがあるのですか？', '["惹かれる気持ちが、すぐに薄れるから", "言葉が、意味を失うから", "タイミングが、ずれて感じられるから", "目に見える手がかりが、言葉を上書きするから"]'::jsonb, '脳は、聞こえるものではなく、見えるものを信頼します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e9e55ffe-f94e-4155-a34b-977fd5d465ba', 'ja', '自信は、主にどうやって築かれますか？', '["前向きに考え、自分を安心させることで", "生まれつきの性格から", "行動を繰り返して、証拠を積み重ねることで", "準備ができるまで、リスクを避けることで"]'::jsonb, '自信は、想像からではなく、行動して乗り越えたという証拠から育ちます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ec90b480-b289-4b95-82b0-39d6020cb7dc', 'ja', 'もともと自信のある男性と、ためらう男性の違いは何ですか？', '["自信のある男性は、繰り返しを通じて、より多くの証拠を積み重ねてきた", "性格が、自信の基本的な高さを決めている", "自信のある男性は、より早い時期に、自分を信じることを学んだ"]'::jsonb, '違いは、積み重ねた証拠です。一方には、頼りにできる証拠があります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f030a547-86d7-4259-a4ec-1734e65a10e0', 'ja', '会話が止まり、気まずく感じます。どう考えるべきですか？', '["「自分は、これが上達することはない」", "「失敗するのは、自分に欠けたところがあるからだ」", "「自分は、こういうことに向いていない」", "「これは情報だ。次は何を変えられるだろう」"]'::jsonb, '成長マインドセットは、つまずきを調整できるものとして捉え、挑戦を続けさせてくれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f41af47d-77fc-439e-bcbf-15e75a29eceb', 'ja', '声をかける前にエネルギーを高められる行動は、どれですか？', '["体を動かすこと", "結果について考えすぎること", "人との関わりから引くこと", "意識してほほえむこと"]'::jsonb, '体の小さな変化が、内面の状態をすばやく変えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f8818fc9-4dc5-4af7-90ed-aa3dc88ca60d', 'ja', '断られるかもしれないと、考えが渦を巻いています。何に意識を向けると助けになりますか？', '["呼吸や、地面についた足など、今この瞬間の感覚", "あらゆる場面への返しを、リハーサルすること", "自分の不安を、弱さだと決めつけること"]'::jsonb, '今ここにある体の感覚は、未来への恐れから注意を引き戻します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('faacab86-d6dc-4688-a30c-5fa3c018c113', 'ja', '人に受け入れられやすくなりたいと思っています。まず何を変えるべきですか？', '["完璧な最初のひと言を用意する", "褒め言葉をリハーサルする", "相手から話しかけてくるのを待つ", "エネルギーを、前向きで開いたものに切り替える"]'::jsonb, 'ポジティブなエネルギーは、言葉を交わす前に、人を招き入れます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ff0646b8-d942-49bb-841f-2415d6f99442', 'ja', 'いつもより長く目を合わせ、何の問題もなく終わります。何に気づくべきですか？', '["証拠ではなく、運が良かっただけだ", "一回だけでは、意味がない", "似た場面で自分を信頼できるという、静かな証拠だ"]'::jsonb, '小さな行動が、脳が自信のよりどころにする記録に積み上がっていきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
